MAX_WORDS = 20
def long_sentences(s:str) -> list:
    "The sentences of `s` that have more than `MAX_WORDS` words."
    return [x for x in re.split(r'(?<=[.?!])\s+', str(s)) if len(re.findall(r"[\w’'{}.:-]+", x)) > MAX_WORDS]

